import { CurrencyPipe, DatePipe } from '@angular/common';
import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { UtilsService } from '../../../../services/utils.service';
import {
  EstadoCuenta,
  Periodo,
  UtilsEstadoCuentaService,
} from '../../services/utils-estado-cuenta.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { UsuarioLogin } from '../../../../auth/auth.model';
import { CreditoPagoService } from '../../../../controllers/credito.pago.service';
import { LoginCliente } from '../../../../clientes/auth/auth.service';
import { CotizadorService } from '../../../cotizador/cotizador.service';

@Component({
  selector: 'app-view-periodos',
  imports: [CurrencyPipe],
  templateUrl: './view-periodos.component.html',
  styleUrl: './view-periodos.component.css',
})
export class ViewPeriodosComponent {
  @Input() credito!: Credito;
  @Input() useLocal?: boolean;

  estadoCuenta?: EstadoCuenta;

  total_a_liquidar = 0;
  periodos: Periodo[] = [];

  totales = {
    totalCuota: 0,
    totalPago: 0,
    totalCapital: 0,
    totalInteres: 0,
    totalIva: 0,
  };

  indexPrimerPeriodo: number = 0;

  toogledAll: boolean = false;

  usuario?: UsuarioLogin;

  constructor(
    public utils: UtilsService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    private creditoPagoController: CreditoPagoService,
    private localStorage: LocalStorageService,
    private cotizador: CotizadorService,
  ) {
    if (this.localStorage.isUserLogged()) {
      this.usuario = this.localStorage.getUser();
    }
  }

  public async regenerarAmortizaciones() {
    await this.limpiarAmortizaciones()
    await this.crearNuevasAmortizaciones()
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['credito']) {
      this.setData();
    }
  }

  esPagadoAdelantado(periodo:Periodo){
    return periodo.status=='PAGADO' && periodo.abonos?.every(a => a.adelantado)
  }

    private crearNuevasAmortizaciones() {
    const pagos = this.cotizador.pagosResponseFromCredito(this.credito)
    return this.creditoPagoController.multipleNews((pagos!.lista_pagos ?? []).map(p => ({
      credito_id: this.credito?.id!,
      fecha: p.fecha,
      pago_fijo: p.pago_fijo,
      abono_a_capital: p.abono_a_capital,
      interes: p.interes,
      iva: p.iva,
      documento_url: '',
    })))
  }

  private async limpiarAmortizaciones() {
    if (!this.credito?.creditos_pagos?.length) return
    return await this.creditoPagoController.multipleUpdate(this.credito.creditos_pagos.map(p => ({
      ...p,
      deleted_at: (new Date()).toISOString().substring(0, 10)
    })))
  }

  async ajustarRedondeo() {
    const amortizaciones =
      this.utilsEstadoCuenta.obtenerAmortizacionesOrdenadas(this.credito);
    amortizaciones.forEach((a) => {
      a.pago_fijo = Math.ceil(+a.abono_a_capital + +a.interes + +a.iva);
    });
    const total_redondeado = amortizaciones.reduce(
      (a, b) => a + b.pago_fijo,
      0,
    );
    const redondeado =
      this.estadoCuenta!.monto_total_mas_intereses - total_redondeado;
    amortizaciones.at(-1)!.pago_fijo -= redondeado;
    await this.creditoPagoController.multipleUpdate(amortizaciones);
    this.credito.estado_cuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(
      this.credito,
      true,
    );
    this.setData();
  }

  async ajustarNoRedondeo() {
    const amortizaciones =
      this.utilsEstadoCuenta.obtenerAmortizacionesOrdenadas(this.credito);
    amortizaciones.forEach((a) => {
      a.pago_fijo = +a.abono_a_capital + +a.interes + +a.iva;
    });
    await this.creditoPagoController.multipleUpdate(amortizaciones);
    this.credito.estado_cuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(
      this.credito,
      true,
    );
    this.setData();
  }

  setData() {
    if (this.useLocal) {
      this.estadoCuenta = this.credito.estado_cuenta;
      console.log(this.estadoCuenta)
    } else {
      this.estadoCuenta = this.utilsEstadoCuenta.getEstadoCuenta(this.credito);
    }

    this.setTotales();

    this.periodos = this.estadoCuenta?.periodos ?? [];
    const primerVigente = this.periodos.find(
      (periodo) => periodo.status == 'VIGENTE',
    );
    if (primerVigente) {
      this.indexPrimerPeriodo = this.periodos.indexOf(primerVigente);
    }
    this.total_a_liquidar = this.estadoCuenta?.total_a_liquidar ?? 0;

    console.log(this.periodos)
  }

  public esElSegundoVigente(index: number): boolean {
    return (
      this.periodos[index].status == 'VIGENTE' &&
      index !== this.indexPrimerPeriodo
    );
  }

  private setTotales() {
    if (!this.estadoCuenta) return;
    this.totales.totalCuota = this.utilsEstadoCuenta.sumarListaByKey(
      'pago_programado_total',
      this.estadoCuenta.periodos.filter((p) => p.status !== 'VIGENTE'),
    );
    this.totales.totalPago = this.estadoCuenta.monto_total_pagado;
    this.totales.totalCapital = this.utilsEstadoCuenta.sumarListaByKey(
      'pago_capital',
      this.estadoCuenta.periodos,
    );
    this.totales.totalInteres = this.utilsEstadoCuenta.sumarListaByKey(
      'pago_interes',
      this.estadoCuenta.periodos,
    );
    this.totales.totalIva = this.utilsEstadoCuenta.sumarListaByKey(
      'pago_iva',
      this.estadoCuenta.periodos,
    );
  }

  toogleAll() {
    this.toogledAll = !this.toogledAll;
    this.estadoCuenta?.periodos.forEach(
      (p) => (p.isExpanded = this.toogledAll),
    );
  }
}
